package com.hospital.service.impl;
import com.hospital.entity.Doctor; import com.hospital.exception.ResourceNotFoundException; import com.hospital.repository.DepartmentRepository; import com.hospital.repository.DoctorRepository; import com.hospital.repository.AppointmentRepository; import com.hospital.repository.MedicalRecordRepository; import com.hospital.service.DoctorService; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class DoctorServiceImpl extends AbstractCrudService<Doctor> implements DoctorService {
 private final DoctorRepository doctors; private final DepartmentRepository departments; private final AppointmentRepository appointments; private final MedicalRecordRepository records;
 public DoctorServiceImpl(DoctorRepository doctors,DepartmentRepository departments,AppointmentRepository appointments,MedicalRecordRepository records){super(doctors);this.doctors=doctors;this.departments=departments;this.appointments=appointments;this.records=records;}
 @Override @Transactional public Doctor create(Doctor d){d.setDoctorId(null);if(d.getEmail()!=null)d.setEmail(d.getEmail().trim());validate(d,null);return doctors.save(d);}
 @Override @Transactional public Doctor update(Integer id,Doctor d){doctors.lockById(id).orElseThrow(()->new com.hospital.exception.ResourceNotFoundException("Doctor not found: "+id));if(d.getEmail()!=null)d.setEmail(d.getEmail().trim());validate(d,id);d.setDoctorId(id);return doctors.save(d);}
 @Override @Transactional public void delete(Integer id){doctors.lockById(id).orElseThrow(()->new com.hospital.exception.ResourceNotFoundException("Doctor not found: "+id));if(appointments.countByDoctorId(id)>0||records.countByDoctorId(id)>0)throw new IllegalArgumentException("Doctor cannot be deleted while appointments or medical records reference them.");doctors.deleteById(id);}
 private void validate(Doctor d,Integer id){if(d.getDoctorName()==null||d.getDoctorName().isBlank())throw new IllegalArgumentException("Doctor name is required.");if(d.getAvailabilityStatus()!=null&&!d.getAvailabilityStatus().isBlank()&&!d.getAvailabilityStatus().equalsIgnoreCase("Available")&&!d.getAvailabilityStatus().equalsIgnoreCase("Unavailable")&&!d.getAvailabilityStatus().equalsIgnoreCase("On Leave"))throw new IllegalArgumentException("Doctor availability must be Available, Unavailable, or On Leave.");if(d.getDepartmentId()!=null)departments.lockById(d.getDepartmentId()).orElseThrow(()->new ResourceNotFoundException("Department not found: "+d.getDepartmentId()));if(d.getEmail()!=null&&!d.getEmail().isBlank())doctors.findByEmailIgnoreCase(d.getEmail().trim()).filter(x->!x.getDoctorId().equals(id)).ifPresent(x->{throw new IllegalArgumentException("Doctor email already exists.");});}
}
